import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, vec2, length, sub, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as primitiveOrbit } from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, CylinderGeometry, TorusKnotGeometry, PlaneGeometry, AmbientLight, DirectionalLight, Color } = ctx.THREE;

  // root group
  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const uvNode = uv();
  const grad0 = color('#0b0b10');
  const grad1 = color('#101017');
  const grad2 = color('#16161d');
  const mix01 = mix(grad0, grad1, smoothstep(0.0, 0.7, uvNode.y));
  const backdropColor = mix(mix01, grad2, smoothstep(0.7, 1.0, uvNode.y));
  backdropMat.colorNode = backdropColor;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- PEDESTAL ----------
  const pedGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32);
  const pedMat = new MeshStandardNodeMaterial();
  pedMat.colorNode = color('#14141a');
  pedMat.roughnessNode = 0.7;
  pedMat.metalnessNode = 0.35;
  const pedestal = new Mesh(pedGeom, pedMat);
  // top face at y = -0.35 => center y = -0.35 - height/2
  pedestal.position.set(0, -0.35 - 0.25, 0);
  root.add(pedestal);

  // ---------- TORUS KNOT ----------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial();
  knotMat.colorNode = color('#e8ecf2'); // fallback albedo
  knotMat.metalnessNode = 0.55;
  knotMat.roughnessNode = 0.55;
  knotMat.clearcoatNode = 0.22;
  knotMat.clearcoatRoughnessNode = 0.35;
  knotMat.anisotropyNode = 0.9;
  knotMat.anisotropyDirectionNode = vec3(0, 0, 1); // rotate 90° to tube direction (approx)
  // load brushed metal map for roughnessMap
  const brushedTexPromise = ctx.textureLoader.loadTexture('/prism-assets/chrome/brushed-metal.map.png');
  brushedTexPromise.then((tex) => {
    knotMat.roughnessMap = tex;
    knotMat.needsUpdate = true;
  });
  const knot = new Mesh(knotGeom, knotMat);
  knot.position.set(0, 0.4, 0);
  root.add(knot);

  // ---------- CONTACT SHADOW ----------
  const shadowGeom = new PlaneGeometry(3, 3);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.transparent = true;
  const uvShadow = uv();
  const center = vec2(0.5, 0.5);
  const dist = length(sub(uvShadow, center));
  const alpha = mix(0.6, 0.0, smoothstep(0.0, 0.4, dist));
  shadowMat.alphaNode = alpha;
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  root.add(shadow);

  // ---------- LIGHTS ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 2);
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-2, -1, -2);
  root.add(rimLight);

  // ---------- TEXT ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 68,
      color: '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // position based on role
    if (item.role === 'headline') {
      txtObj.position.set(0, -1.2, 0);
    } else {
      // caption
      txtObj.position.set(0, -1.6, 0);
    }
    root.add(txtObj);
  }

  // ---------- CINEMATIC PRIMITIVE ----------
  const primitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitives.push(instance);
      }
    }
  }

  // ---------- USERDATA ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose materials
    [backdropMat, pedMat, knotMat, shadowMat].forEach((mat) => {
      if (mat) {
        mat.dispose();
      }
    });
    // dispose textures
    brushedTexPromise.then((tex) => tex.dispose());
    // cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
    // kill any GSAP timelines (none used here)
    gsap.globalTimeline.clear();
  };

  return root;
}
